const body = $json.body || $json;
const clean = (s, n) => (typeof s === 'string' ? s.trim().slice(0, n || 300) : '');

const agent = clean(body.agent, 30);
const task = clean(body.task, 4000);
const business = clean(body.business) || '';
const extra = clean(body.extra, 3000);

// The Chester County towns Nick sells into → tight bounding boxes (south,west,north,east)
const TOWNS = {
  'west chester': '39.93,-75.65,40.00,-75.55',
  'downingtown': '39.98,-75.75,40.03,-75.68',
  'coatesville': '39.96,-75.85,40.02,-75.78',
  'exton': '39.99,-75.68,40.05,-75.60',
  'phoenixville': '40.10,-75.55,40.16,-75.48',
  'malvern': '39.99,-75.55,40.05,-75.48',
  'kennett square': '39.82,-75.75,39.88,-75.68',
  'paoli': '40.01,-75.52,40.06,-75.46',
  'chester county': '39.85,-75.85,40.15,-75.45'
};

const hay = (business + ' ' + task).toLowerCase();
let town = 'chester county';
const names = Object.keys(TOWNS);
for (let i = 0; i < names.length; i++) {
  if (hay.indexOf(names[i]) !== -1) { town = names[i]; break; }
}
const bbox = TOWNS[town];

// Real barbershops / salons in that box, straight from OpenStreetMap (free, no key).
// Nodes only — dropping ways keeps the query light enough to answer in seconds.
const ql = '[out:json][timeout:40];(node["shop"="hairdresser"](' + bbox + ');node["shop"="beauty"](' + bbox + '););out body 50;';
const osmUrl = 'https://overpass-api.de/api/interpreter?data=' + encodeURIComponent(ql);

return [{ json: { agent, task, business, extra, town, osmUrl } }];

const src = $('Pick Area').item.json;
const agent = src.agent;
const task = src.task;
const business = src.business;
const extra = src.extra;
const town = src.town;

if (!task) return [{ json: { error: 'no task given' } }];

// Real shops pulled live from OpenStreetMap. If the lookup failed we simply carry on without them.
let shopBlock = '';
try {
  const els = ($json && $json.elements) || [];
  const rows = [];
  for (let i = 0; i < els.length && rows.length < 40; i++) {
    const t = els[i].tags || {};
    if (!t.name) continue;
    const addr = [t['addr:housenumber'], t['addr:street']].filter(Boolean).join(' ');
    const site = t.website || t['contact:website'] || 'NO WEBSITE';
    const phone = t.phone || t['contact:phone'] || 'no phone listed';
    rows.push('· ' + t.name + ' — ' + (addr || 'address not listed') + ', ' + (t['addr:city'] || town) + ' — ' + phone + ' — ' + site);
  }
  if (rows.length) {
    shopBlock =
      'REAL SHOPS, pulled live from OpenStreetMap for ' + town.toUpperCase() + ' right now\n' +
      '(name — address — phone — website). "NO WEBSITE" means none is on record, which is exactly the gap Nick walks through:\n' +
      rows.join('\n') + '\n\n' +
      'RULES FOR THIS DATA: use ONLY these shops. Never invent a shop name, address or phone number. ' +
      'Rank the NO WEBSITE ones first. If the list is thin, say so plainly instead of padding it with made-up shops.\n\n';
  }
} catch (e) { /* no shop data — carry on */ }

const TB = "You work for TB Solutions, Nick Byrd's one-man digital agency in Chester County, PA (tbsol.net). Flagship product: Loop for Barbershops (thebarberloop.com) — a done-for-you bundle of website, own-brand booking (the anti-Booksy: no marketplace, no per-booking cut), loyalty rewards card with points/streaks, referral links, SMS win-backs, and an in-chair arcade with real prizes. Free to try live; paid tier is done-for-you setup. Leads land in Supabase and surface in the CRM. Voice: short punchy lines, concrete over clever, zero corporate jargon. Nick works from his phone — keep output skimmable and immediately usable.";

const A = {
  'lead-gen': "You are the lead generation specialist. Work the real shop list below: qualify each by its web-presence gap (no website first, then weak listing or marketplace-only), and write short human outreach. Winning frame: show-don't-pitch — \"I already built your site, want to see it?\". Every message fits one phone screen, one ask, never sounds like an agency blast.",
  'research': "You are the research analyst. Answer the decision question in three sentences first, then evidence: competitor pricing (Booksy, Squire, GlossGenius, Fresha), what users complain about, and the one exploitable gap. Separate sourced fact from your labeled read. Never present a guess as a finding.",
  'copywriter': "You are the conversion copywriter. Second person, present tense, short lines (\"Your chair is full. Your calendar isn't.\"). One primary CTA per piece. Kill objections where they occur. SMS under 160 chars, sounds like a person. Concrete over clever, always.",
  'ui-designer': "You are the UI designer for a dark cinematic house style: bg #07080c, glass panels, Poppins display + Inter body, gradient accents (Loop: #5df2e0 to #6f9dff), real photography over gradient cards, mobile-first (barbers on phones ~390px). Framework-free single-file HTML pages, vanilla JS. Describe or write complete, drop-in code.",
  'graphics': "You are the graphics art director. Cinematic, moody, real-photography feel; dark bases near #07080c so images sit on the site; teal/blue accent light, warm gold sparingly; authentic barbershop scenes, never stocky. Deliver detailed image-generation prompts, shot lists, and composition notes (OG images 1200x630, heroes need mobile + desktop crops). No text baked into images.",
  'marketing': "You are the marketing strategist for a one-man agency. Local-first: Google Business completeness, review velocity, \"barber near me\". Every campaign = one audience, one offer, one channel, one measurable. Offers beat ads; the free pre-built website is the proven door opener. End every plan with this-week actions ordered by impact.",
  'script-writer': "You are the short-form video script writer. Hook in the first 1.5 seconds, write in beats: [SHOT] / VO or overlay / seconds — ~6 beats per 30s. One CTA max as the natural last beat. Sound native to TikTok/Reels — real barbershop talk, no \"Hey guys\". Pitch formats as repeatable series with 3 example episodes.",
  'client-handler': "You are the client success manager. Clients are barbers and local owners — busy, on phones, allergic to corporate email. Draft messages at text-length, first name, one purpose. Onboarding = checklist with owner-visible wins (site live, link in bio, Google listing, rewards QR, first SMS). Churn saves lead with value, never \"just checking in\". You draft; Nick sends.",
  'saas-ops': "You are the SaaS product operator for Loop. Score every idea against \"does this book more chairs or save Nick time\". The roadmap is what a one-man shop can ship — kill scope, not quality. Report as: decisions-needed / done / watching, actionable in five minutes. Numbers over impressions.",
  'partnerships': "You are the partnerships lead. Existing machinery: affiliate ?ref= links with end-to-end attribution, reps who sell Loop per city, in-product ambassador referrals. Design one-page deals: who does what, who gets paid what and when, tracked through the ref system (no honor-system deals), clean exits. Recurring beats one-time. You draft; Nick signs."
};

const persona = A[agent];
if (!persona) return [{ json: { error: 'unknown agent — use one of: ' + Object.keys(A).join(', ') } }];

// Shop data helps the agents that work the street; the others do not need it.
const wantsShops = ['lead-gen', 'marketing', 'client-handler', 'partnerships'].indexOf(agent) !== -1;
const ctx = [business ? 'Client/business in focus: ' + business : '', extra ? 'Extra context: ' + extra : ''].filter(Boolean).join('\n');

const prompt = persona + '\n\n' + TB + '\n\n' +
  (wantsShops ? shopBlock : '') +
  (ctx ? ctx + '\n\n' : '') +
  'TASK FROM NICK:\n' + task + '\n\n' +
  'Deliver the finished work itself — not a plan to do it. Be specific to the niche and location; no generic fluff.';

return [{ json: { prompt, agent, town, shopsFound: shopBlock ? true : false } }];
